What is the output of "pin1" if "pin2" is sent "1011" where 1 is 5V and 0 is 0V?

```cpp
int pin1 = 12;
int pin2 = 11;

void setup() {
  pinMode(pin1, OUTPUT);
  pinMode(pin2, INPUT);
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(pin2) == 1) {
    digitalWrite(pin1, LOW);
  }
  else if (digitalRead(pin2) == 0) {
    digitalWrite(pin1, HIGH);
  }
}
```

What is the objective of the code given below if it is executed on the Arduino Uno?

```cpp
#include <EEPROM.h>

int pin = 13;

void setup() {
  pinMode(pin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  for (int i = 0; i < EEPROM.length(); i++) {
    EEPROM.write(i, 1);
  }

  digitalWrite(pin, HIGH);
  exit(0);
}
```

What is the time period of the output signal of the program given below?

```cpp
int pin = 10;

void setup() {
  Serial.begin(9600);
  pinMode(pin, OUTPUT);
}

void loop() {
  digitalWrite(pin, HIGH);
  delay(10);
  digitalWrite(pin, LOW);
  delay(10);
}
```

