What happens to the LED's blink rate in the given code when the potentiometer is turned all the way to provide the maximum voltage to the analog pin?

```cpp
const int ledPin = 13;
const int sensorPin = A0;
int sensorValue = 0;

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  sensorValue = analogRead(sensorPin);
  Serial.println(sensorValue);
  digitalWrite(ledPin, HIGH);
  delay(sensorValue);
  digitalWrite(ledPin, LOW);
  delay(sensorValue);
}
```

